function weather(day){let slug=loc.id.replace(/-county$/,'').replace(/-city$/,'');if(loc.id==='fairfax-city')slug='fairfax-city';if(loc.id==='falls-church-city')slug='falls-church';return DATA.weather[`${slug}-${year}-general`]?.[day]||null;}
