const siteName=k=>schedule()?.sites.find(s=>s.key===k)?.name||DATA.sites.find(s=>s.key===k)?.name||k.split('_').map(x=>x[0].toUpperCase()+x.slice(1)).join(' ');
function schedule(){return DATA.calendars?.[loc.id]?.[year]||null;}
function hoursFor(site,day){return schedule()?.hours?.[site]?.[day]||null;}
function hourCount(block){if(!block)return null;return (Number(block[1].slice(0,2))*60+Number(block[1].slice(3))-Number(block[0].slice(0,2))*60-Number(block[0].slice(3)))/60;}
function siteReport(){return DATA.siteReports?.[loc?.id]?.[year]||official()}
function siteRows(){const o=siteReport();if(!o)return [];return o.userReport&&!o.history.some(r=>r.date===o.userReport.date)?[...o.history,o.userReport].sort((a,b)=>a.date.localeCompare(b.date)):o.history;}
function drawSites(){const o=siteReport(),sc=schedule(),keys=o?.siteKeys?.length?o.siteKeys:sc?.sites?.map(s=>s.key)||[];if(!keys.length){$('site-content').innerHTML='<p class="empty">Site-level turnout unavailable.</p>';return}const totals=Object.fromEntries(keys.map(k=>[k,siteRows().reduce((a,r)=>a+(r.sites?.[k]||0),0)])),total=d3.sum(Object.values(totals));$('site-content').innerHTML=`<div class="site-grid"><div><div id="site-map" class="map"></div><div id="site-tip" class="chart-detail">Select a location.</div></div><div class="table-scroll"><table class="site-table"><thead><tr><th>Location</th><th>${o?.coverage==='partial'?'Reported ballots':'Ballots'}</th><th>Share</th></tr></thead><tbody>${keys.slice().sort((a,b)=>totals[b]-totals[a]).map(k=>`<tr><td>${esc(siteName(k))}</td><td>${o?.siteKeys.length?num(totals[k]):'—'}</td><td>${o?.siteKeys.length?pct(totals[k],total):'—'}</td></tr>`).join('')}</tbody></table></div></div><p class="small-note">${o?.siteKeys.length?`${date(siteRows()[0].date)}${siteRows().length>1?' – '+date(siteRows().at(-1).date):''} · <a href="${o.source}" target="_blank" rel="noopener">Local source</a>${o.coverage==='partial'?' · Available dates only':''}`:'Site-level turnout unavailable.'} </p>`;
 const region=GEO?.features.find(f=>f.properties.id===loc.id),locations=keys.map(k=>({...DATA.sites.find(s=>s.key===k),...sc?.sites.find(s=>s.key===k),key:k})).filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon));if(!region||!locations.length){$('site-map').innerHTML='<p class="empty">Location map unavailable.</p>';return}const W=500,H=350,geo={type:'FeatureCollection',features:[region]},proj=d3.geoMercator().fitExtent([[15,15],[W-15,H-15]],geo);const svg=d3.select('#site-map').append('svg').attr('viewBox',`0 0 ${W} ${H}`);svg.append('path').datum(region).attr('d',d3.geoPath(proj)).attr('fill','#dce8ef').attr('stroke','white');const max=d3.max(Object.values(totals))||1;svg.selectAll('circle').data(locations).join('circle').attr('cx',s=>proj([s.lon,s.lat])[0]).attr('cy',s=>proj([s.lon,s.lat])[1]).attr('r',s=>5+Math.sqrt(totals[s.key]/max)*9).attr('fill',COLORS.early).attr('stroke','white').attr('stroke-width',2).attr('tabindex',0).attr('role','button').attr('aria-label',s=>s.name||siteName(s.key)).style('cursor','pointer').on('mouseenter',(_,s)=>tip(s)).on('focus',(_,s)=>tip(s)).on('click',(_,s)=>tip(s));function tip(s){$('site-tip').innerHTML=`<strong>${esc(s.name||siteName(s.key))}</strong><div class="detail-values"><span>${esc(s.address||'')}</span><span>${o?`${num(totals[s.key])} ballots · ${pct(totals[s.key],total)} of reported early voting`:'Turnout unavailable'}</span></div>`;}}
let heatMetric='ballots',heatNumbers=true,heatFit=false;
function drawHeat(){const o=siteReport();if(!o?.siteKeys.length){$('heat-content').innerHTML='<p class="empty">Daily site counts unavailable.</p>';return}const rows=trimZeros(siteRows(),r=>Object.values(r.sites||{}).some(v=>v!=null&&v!==0));function aggregate(rr,ks){let ballots=0,hours=0,found=false;for(const r of rr)for(const k of ks){const v=r.sites?.[k],h=hourCount(hoursFor(k,r.date));if(v!=null&&(heatMetric!=='rate'||h)){ballots+=v;hours+=h||0;found=true}}return found?(heatMetric==='rate'?(hours?ballots/hours:null):ballots):null}const keys=o.siteKeys.slice().sort((a,b)=>aggregate(rows,[b])-aggregate(rows,[a])),cumulative={};for(const k of keys){let total=0;for(const r of rows){if(r.sites?.[k]!=null)total+=r.sites[k];cumulative[r.date+'|'+k]=r.sites?.[k]==null?null:total}}const value=(r,k)=>heatMetric==='cumulative'?cumulative[r.date+'|'+k]:heatMetric==='rate'?(hourCount(hoursFor(k,r.date))&&r.sites?.[k]!=null?r.sites[k]/hourCount(hoursFor(k,r.date)):null):r.sites?.[k];const max=d3.max(rows,r=>d3.max(keys,k=>value(r,k)))||1,color=d3.scaleSequential(t=>d3.interpolateBlues(.15+.65*t)).domain([0,max]);
 $('heat-content').innerHTML=`<div class="controls heat-controls"><div class="segmented"><button id="heat-ballots" aria-pressed="${heatMetric==='ballots'}">Daily ballots</button><button id="heat-cumulative" aria-pressed="${heatMetric==='cumulative'}">${o.coverage==='partial'?'Cumulative reported':'Cumulative ballots'}</button><button id="heat-rate" aria-pressed="${heatMetric==='rate'}">Ballots/hour</button></div><div class="heat-options"><button class="method" id="heat-numbers" aria-pressed="${heatNumbers&&!heatFit}" ${heatFit?'disabled':''}><span class="toggle-check">${heatNumbers&&!heatFit?'✓':''}</span>Show numbers</button><button class="method" id="heat-fit" aria-pressed="${heatFit}"><span class="toggle-check">${heatFit?'✓':''}</span>Fit all dates</button></div></div><div class="table-scroll heatwrap"><table class="site-rhythm ${heatFit?'fit':''}"><thead><tr><th>Location</th><th>${heatMetric==='rate'?'Avg./hr':'Total'}</th>${rows.map((r,i)=>`<th class="date-col ${[0,6].includes(utc(r.date).getUTCDay())?'weekend-date':''}"><span>${!heatFit||i%7===0?utc(r.date).toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'}):''}</span><small>${!heatFit||i%7===0?(Number(r.date.slice(5,7))+'/'+Number(r.date.slice(8))):''}</small></th>`).join('')}</tr></thead><tbody>${keys.map(k=>`<tr><th class="site-label" title="${esc(siteName(k))}">${esc(siteName(k).replace('Government Center','Govt. Center'))}</th><td class="site-total">${num(aggregate(rows,[k]))}</td>${rows.map(r=>{const v=value(r,k);return `<td class="heat ${v==null?'unknown':''}" data-heat="${r.date}|${k}" tabindex="0" role="button" aria-label="${esc(siteName(k))}, ${date(r.date)}: ${v==null?'unavailable':num(v)}" style="${v==null?'':`background:${color(v)};color:${v/max>.55?'white':'#173b60'}`}" ><span>${heatNumbers&&!heatFit?(v==null?'':num(v)):''}</span></td>`}).join('')}</tr>`).join('')}</tbody><tfoot><tr><th>Total${heatMetric==='rate'?' / hr':''}</th><td>${num(aggregate(rows,keys))}</td>${rows.map((r,i)=>`<td>${heatFit?'':num(aggregate(heatMetric==='cumulative'?rows.slice(0,i+1):[r],keys))}</td>`).join('')}</tr></tfoot></table></div><div id="heat-tip" class="chart-detail">Select a day and site.</div><div class="heat-scale"><span>0</span><i></i><span>${num(max)}</span></div>`;
 $('heat-ballots').onclick=()=>{heatMetric='ballots';drawHeat()};$('heat-cumulative').onclick=()=>{heatMetric='cumulative';drawHeat()};$('heat-rate').onclick=()=>{heatMetric='rate';drawHeat()};$('heat-numbers').onclick=()=>{heatNumbers=!heatNumbers;drawHeat()};$('heat-fit').onclick=()=>{heatFit=!heatFit;drawHeat()};document.querySelectorAll('[data-heat]').forEach(el=>{function tip(){const[d,k]=el.dataset.heat.split('|'),r=rows.find(r=>r.date===d),h=hourCount(hoursFor(k,d));$('heat-tip').innerHTML=`<strong>${date(d)} · ${esc(siteName(k))}</strong><div class="detail-values"><span>Daily: <b>${num(r.sites?.[k])}</b></span><span>Cumulative: <b>${num(cumulative[d+'|'+k])}</b></span><span>Hours: <b>${hoursFor(k,d)?hoursFor(k,d).map(clock).join(' – '):'Unavailable'}</b></span><span>Ballots/hour: <b>${h&&r.sites?.[k]!=null?num(r.sites[k]/h):'—'}</b></span>${weatherChip(weather(d))}</div>`}el.onclick=tip;el.onmouseenter=tip;el.onfocus=tip;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();tip()}}})}

function drawDailyTable(){const rows=ballotRows(),isOfficial=chartSource==='official',keys=isOfficial?['early','postal','dropbox']:['early','mail'];$('daily-table').innerHTML=`<p class="note">${isOfficial?'County daily report':'DAL reporting snapshots'} · Earliest first</p><div class="table-scroll"><table><thead><tr><th>Date</th>${keys.map(k=>`<th>${methodLabel(k)}</th>`).join('')}<th>Cumulative ballots</th><th>Turnout</th><th>Weather</th></tr></thead><tbody>${rows.map((r,i)=>{const w=weather(r.date),total=isOfficial?r.cumulative.early+r.cumulative.postal+r.cumulative.dropbox:r.total;return `<tr><td>${short(r.date)}</td>${keys.map(k=>`<td>${num(isOfficial?r[k]:k==='early'?r.deltaEarly:r.deltaMail)}</td>`).join('')}<td>${num(total)}</td><td>${pct(total,loc.registered)}</td><td>${weatherChip(w)||'—'}</td></tr>`}).join('')}</tbody></table></div><p class="small-note"><a href="https://open-meteo.com/">Weather: Open-Meteo</a> · CC BY 4.0</p>`;}
