function mapControls(){for(const id of ['map-method','map-measure']){const select=$(id);if(!select)continue;select.closest('label')?.classList.add('hidden');if(!select.closest('label'))select.classList.add('hidden');const div=document.createElement('div');div.className='segmented '+(id==='map-method'?'map-method-buttons':'');div.innerHTML=[...select.options].map(o=>`<button data-value="${o.value}" ${o.disabled?'disabled':''} aria-pressed="${o.value===select.value}">${o.text}</button>`).join('');select.parentElement.parentElement.append(div);div.querySelectorAll('button').forEach(b=>b.onclick=()=>{select.value=b.dataset.value;div.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));drawMap()})}const expand=document.createElement('button');expand.className='expand-map';expand.textContent='Expand map ⛶';expand.onclick=()=>{const section=$('precincts'),full=section.classList.toggle('map-expanded');document.body.classList.toggle('map-open',full);if(full){section.setAttribute('role','dialog');section.setAttribute('aria-modal','true');section.setAttribute('aria-label','Expanded precinct map')}else{section.removeAttribute('role');section.removeAttribute('aria-modal');section.removeAttribute('aria-label')}expand.textContent=full?'Close map ×':'Expand map ⛶';drawMap()};$('precincts').querySelector('.section-head').append(expand)}
