const clock=t=>{const[h,m]=t.split(':').map(Number);return(h%12||12)+(m?':'+String(m).padStart(2,'0'):'')+(h>=12?' PM':' AM')};
function trimZeros(rows,active){const start=rows.findIndex(active);if(start<0)return rows.slice(-1);let end=rows.length-1;while(end>start&&!active(rows[end]))end--;return rows.slice(start,end+1)}
function reportLabel(r){return 'Data through '+date(r.activityDate||r.date);}
