 ['daily','cumulative'].forEach(m=>$('planning-'+m).onclick=()=>{planningView.mode=m;drawPlanning(expanded)});if(expanded){$('planning-demand').onchange=e=>{planningView.demand=+e.target.value/100;drawPlanning(true)};$('planning-hours').onchange=e=>{planningView.hours=+e.target.value/100;drawPlanning(true)};$('planning-alpha').onchange=e=>{planningView.alpha=e.target.value==='auto'?null:+e.target.value;drawPlanning(true)};document.querySelectorAll('[data-reference]').forEach(b=>b.onclick=()=>{const active=new Set(planningView.years||choices.map(v=>v.k));if(active.has(b.dataset.reference)){if(active.size===1)return;active.delete(b.dataset.reference)}else active.add(b.dataset.reference);planningView.years=[...active];drawPlanning(true)});$('planning-reset').onclick=()=>{planningView={key,mode:planningView.mode,demand:1,hours:1,alpha:null,years:null};drawPlanning(true)}}drawPlanningChart(result);
