function reorderSections(){const app=$('app');for(const id of ['ballots','scenario-preview','historical','sites','site-days','precincts','official','every-number','calendar-section'])if($(id))app.append($(id));}

function weatherIcon(wet,snowy){const cloud='<path class="wx-cloud" d="M6.2 12.2a3 3 0 0 1 .5-6 4.2 4.2 0 0 1 8 .9 2.6 2.6 0 0 1-.4 5.1H6.2Z"/>';return `<svg class="wx-icon" width="16" height="16" viewBox="0 0 20 20" aria-hidden="true" focusable="false">${snowy?cloud+[5,9.5,14].map((x,i)=>`<g class="wx-flake" style="animation-delay:${i*.4}s"><line x1="${x-1.4}" y1="15.4" x2="${x+1.4}" y2="15.4"/><line x1="${x}" y1="14" x2="${x}" y2="16.8"/></g>`).join(''):wet?cloud+[4.5,8.5,12.5].map((x,i)=>`<line class="wx-drop" x1="${x+6}" y1="13.5" x2="${x+4.6}" y2="17" style="animation-delay:${i*.26}s"/>`).join(''):'<circle cx="10" cy="10" r="4" class="wx-sun"/>'}</svg>`}

function compositionBar(parts,total,cls=''){return `<div class="composition-bar ${cls}" role="img" aria-label="${esc(parts.map(p=>p.label+': '+num(p.value)+' ('+pct(p.value,total)+')').join(', '))}">${parts.filter(p=>p.value>0).map(p=>{const share=total?p.value/total*100:0;return `<div style="width:${share}%;background:${p.color};color:${p.ink||'white'}" title="${esc(p.label)}: ${num(p.value)} (${pct(p.value,total)})">${share>=12?`<span>${share>=45?esc(p.label)+' ':''}<b>${share.toFixed(0)}%</b></span>`:''}</div>`}).join('')}</div>`}
