function drawMethodBreakdown(r){const o=official(),row=o?.history.filter(v=>v.date<=r.date).at(-1),c=row?.cumulative,county=c&&Number.isFinite(c.postal)&&Number.isFinite(c.dropbox),early=county?c.early:r.early,mail=county?c.postal+c.dropbox:r.mail,total=early+mail,parts=[{label:'Early in-person',value:early,color:COLORS.early},{label:'Vote-by-mail',value:mail,color:COLORS.mail}],returns=county?[{label:'By mail',value:c.postal,color:COLORS.mail},{label:'Drop box',value:c.dropbox,color:COLORS.dropbox,ink:'#153d61'}]:null;
 $('mix').innerHTML=`<p class="composition-total"><b>${num(total)}</b> early ballots</p>${compositionBar(parts,total)}${returns&&mail?`<div class="return-subbar" style="width:${100*mail/total}%;margin-left:${100*early/total}%">${compositionBar(returns,mail,'small')}</div>`:''}${compositionLegend(parts,total)}${returns?`<div class="return-method-label">Mail-return methods</div>${compositionLegend(returns,mail)}`:''}${county?`<p class="composition-source"><a href="${o.source}" target="_blank" rel="noopener">County report · ${short(row.date)}</a></p>`:''}`;
 const latest=county&&row.date===o.history.at(-1).date,extras=latest?o.extras:null,switched=extras?.switchedTotal??(extras?.switchedSurrendered!=null?extras.switchedSurrendered+extras.switchedNotSurrendered:null),issued=county?c.sent:r.outstanding==null?null:r.mail+r.outstanding;
 if(!issued){$('mail-status').innerHTML='<p class="empty">Mail status unavailable.</p>';return}let status;if(county){const remainder=Math.max(0,issued-mail-(switched||0));status=[...returns,...(switched!=null?[{label:'Voted in person instead',value:switched,color:'#a9cced',ink:'#173b60'}]:[]),{label:switched!=null?'Not returned':'Other / not returned',value:remainder,color:'#d8dde7',ink:'#172337'}]}else status=[{label:'Returned',value:r.mail,color:COLORS.mail},{label:'Outstanding',value:r.outstanding,color:'#d8dde7',ink:'#172337'}];$('mail-status').innerHTML=`<p class="composition-total"><b>${num(issued)}</b> ${county?'ballots issued':'tracked mail ballots'}</p>${compositionBar(status,issued)}${compositionLegend(status,issued)}${extras?.undeliverable!=null?`<p class="composition-source">${num(extras.undeliverable)} undeliverable</p>`:''}${county?`<p class="composition-source"><a href="${o.source}" target="_blank" rel="noopener">County report · ${short(row.date)}</a></p>`:''}`}

// Single public Fairfax series. Raw DPW histories remain preserved in region.json.
function preferCountyReports(data){
 for(const [k,o] of Object.entries(data.official||{})){
  const e=data.elections[k],l=e?.localities.find(l=>l.id==='fairfax-county');if(!l||!o.history?.length)continue;
  const rows=o.history.filter(r=>r.cumulative&&['early','postal','dropbox'].every(m=>Number.isFinite(r.cumulative[m]))).map(r=>({date:r.date,activityDate:r.date,reportDate:o.reportDate||null,source:o.source,early:r.cumulative.early,mail:r.cumulative.postal+r.cumulative.dropbox,total:r.cumulative.early+r.cumulative.postal+r.cumulative.dropbox,outstanding:null}));
  if(rows.length){l.history=rows;l.source=o.source;if(o.registered){l.registered=o.registered;l.registrationDate=o.reportDate;}}
 }return data;
}

function drawStateSchedule(){const info=DATA.satellites?.[year]?.[loc.id],meta=DATA.names.find(n=>n.id===loc.id);$('schedule-content').innerHTML=(info?.sites.length?`<div class="schedule-cards">${info.sites.map(s=>`<article><h3>${esc(s.name)}</h3><p>${esc(s.address)}</p><b>Opens ${short(s.firstOpen)}</b><ul>${s.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></article>`).join('')}</div><a href="${info.source}" target="_blank" rel="noopener">Official locations & hours ↗</a>`:'<p class="note">Detailed schedule not yet loaded.</p>')+`<p><a href="${meta?.officeSource||'https://www.elections.virginia.gov/casting-a-ballot/early-voting-office-locations/'}" target="_blank" rel="noopener">Local election office · dates & hours ↗</a></p>`;}
